import{_ as e,o as n,c as o,a2 as i}from"./chunks/framework.CC9cRD7J.js";const s="/Staff-wiki/gui-bangui.svg",m=JSON.parse('{"title":"Panel Gráfico de Bans (/bangui)","description":"","frontmatter":{},"headers":[],"relativePath":"moderacion/ban-gui.md","filePath":"moderacion/ban-gui.md","lastUpdated":1793575385000}'),t={name:"moderacion/ban-gui.md"};function r(l,a,d,c,u,p){return n(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="panel-grafico-de-bans-bangui" tabindex="-1">Panel Gráfico de Bans (/bangui) <a class="header-anchor" href="#panel-grafico-de-bans-bangui" aria-label="Permalink to &quot;Panel Gráfico de Bans (/bangui)&quot;">​</a></h1><p><img src="'+s+'" alt="Panel Gráfico de Bans de StaffPlus"></p><p>Para facilitar la moderación sin tener que memorizar comandos o sintaxis de tiempo, StaffPlus incluye una interfaz gráfica interactiva completa:</p><hr><h2 id="🖥️-apertura-del-panel" tabindex="-1">🖥️ Apertura del Panel <a class="header-anchor" href="#🖥️-apertura-del-panel" aria-label="Permalink to &quot;🖥️ Apertura del Panel&quot;">​</a></h2><ul><li><strong>Abrir panel general o sobre un jugador:</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/bangui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [jugador]</span></span></code></pre></div><em>Permiso requerido:</em> <code>staffplus.ban</code><em>Aliases disponibles:</em> <code>/banmenu</code>, <code>/banpanel</code>.</li></ul><hr><h2 id="🧩-componentes-del-menu" tabindex="-1">🧩 Componentes del Menú <a class="header-anchor" href="#🧩-componentes-del-menu" aria-label="Permalink to &quot;🧩 Componentes del Menú&quot;">​</a></h2><h3 id="_1-selector-de-tipo-de-sancion" tabindex="-1">1. Selector de Tipo de Sanción <a class="header-anchor" href="#_1-selector-de-tipo-de-sancion" aria-label="Permalink to &quot;1. Selector de Tipo de Sanción&quot;">​</a></h3><ul><li><strong>Ban de Jugador (Cabeza de jugador):</strong> Sanciona la cuenta/UUID del usuario.</li><li><strong>Ban de IP (Bloque de redstone):</strong> Sanciona la dirección IP asociada al usuario. Puedes alternar entre ambos modos con un solo clic.</li></ul><h3 id="_2-botones-de-duracion-rapida" tabindex="-1">2. Botones de Duración Rápida <a class="header-anchor" href="#_2-botones-de-duracion-rapida" aria-label="Permalink to &quot;2. Botones de Duración Rápida&quot;">​</a></h3><ul><li><strong>1 Hora:</strong> Para faltas leves o advertencias con suspensión.</li><li><strong>1 Día:</strong> Para conducta tóxica o insultos reiterados.</li><li><strong>7 Días:</strong> Para abuso de bugs menores o trampas moderadas.</li><li><strong>30 Días:</strong> Para faltas graves.</li><li><strong>Permanente (Barrera):</strong> Veto definitivo del servidor.</li></ul><h3 id="_3-presets-de-motivos-comunes" tabindex="-1">3. Presets de Motivos Comunes <a class="header-anchor" href="#_3-presets-de-motivos-comunes" aria-label="Permalink to &quot;3. Presets de Motivos Comunes&quot;">​</a></h3><ul><li><strong>Uso de Hacks / Cheats:</strong> Trampas de movimiento, combate o visión.</li><li><strong>Toxicidad / Spam:</strong> Conducta antideportiva o inundación de mensajes.</li><li><strong>Acoso / Lenguaje Inapropiado:</strong> Falta de respeto grave a miembros de la comunidad.</li><li><strong>Abuso de Bugs:</strong> Explotación de errores para beneficio económico o ventajas de juego.</li></ul><h3 id="_4-gestor-de-sanciones-activas-banlistgui" tabindex="-1">4. Gestor de Sanciones Activas (<code>BanListGui</code>) <a class="header-anchor" href="#_4-gestor-de-sanciones-activas-banlistgui" aria-label="Permalink to &quot;4. Gestor de Sanciones Activas (`BanListGui`)&quot;">​</a></h3><p>Al pie de la interfaz, el botón de <strong>Sanciones Activas</strong> te permite ver una lista paginada de todos los jugadores e IPs baneados actualmente.</p><ul><li>Cada objeto muestra quién aplicó la sanción, la razón y el tiempo restante.</li><li><strong>Desbanear en un clic:</strong> Hacer clic izquierdo sobre cualquier sanción activa en la lista levanta el ban inmediatamente.</li></ul>',17)])])}const b=e(t,[["render",r]]);export{m as __pageData,b as default};
